BNGParser::BNGParser(TokenStream *input) : BNGParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

BNGParser::BNGParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  BNGParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *bngparserParserStaticData->atn, bngparserParserStaticData->decisionToDFA, bngparserParserStaticData->sharedContextCache, options);
}

BNGParser::~BNGParser() {
  delete _interpreter;
}

const atn::ATN& BNGParser::getATN() const {
  return *bngparserParserStaticData->atn;
}

std::string BNGParser::getGrammarFileName() const {
  return "BNGParser.g4";
}

const std::vector<std::string>& BNGParser::getRuleNames() const {
  return bngparserParserStaticData->ruleNames;
}

const dfa::Vocabulary& BNGParser::getVocabulary() const {
  return bngparserParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView BNGParser::getSerializedATN() const {
  return bngparserParserStaticData->serializedATN;
}


//----------------- ProgContext ------------------------------------------------------------------

BNGParser::ProgContext::ProgContext(ParserRuleContext *parent, size_t invokingState)
  : ParserRuleContext(parent, invokingState) {
}

tree::TerminalNode* BNGParser::ProgContext::EOF() {
  return getToken(BNGParser::EOF, 0);
}

std::vector<tree::TerminalNode *> BNGParser::ProgContext::LB() {
  return getTokens(BNGParser::LB);
}

tree::TerminalNode* BNGParser::ProgContext::LB(size_t i) {
  return getToken(BNGParser::LB, i);
}

std::vector<BNGParser::Header_blockContext *> BNGParser::ProgContext::header_block() {
  return getRuleContexts<BNGParser::Header_blockContext>();
}

BNGParser::Header_blockContext* BNGParser::ProgContext::header_block(size_t i) {
  return getRuleContext<BNGParser::Header_blockContext>(i);
}

std::vector<BNGParser::Action_commandContext *> BNGParser::ProgContext::action_command() {
  return getRuleContexts<BNGParser::Action_commandContext>();
}

BNGParser::Action_commandContext* BNGParser::ProgContext::action_command(size_t i) {
  return getRuleContext<BNGParser::Action_commandContext>(i);
}

BNGParser::Wrapped_actions_blockContext* BNGParser::ProgContext::wrapped_actions_block() {
  return getRuleContext<BNGParser::Wrapped_actions_blockContext>(0);
}

BNGParser::Actions_blockContext* BNGParser::ProgContext::actions_block() {
  return getRuleContext<BNGParser::Actions_blockContext>(0);
}

tree::TerminalNode* BNGParser::ProgContext::BEGIN() {
  return getToken(BNGParser::BEGIN, 0);
}

std::vector<tree::TerminalNode *> BNGParser::ProgContext::MODEL() {
  return getTokens(BNGParser::MODEL);
}

tree::TerminalNode* BNGParser::ProgContext::MODEL(size_t i) {
  return getToken(BNGParser::MODEL, i);
}

std::vector<BNGParser::Program_blockContext *> BNGParser::ProgContext::program_block() {
  return getRuleContexts<BNGParser::Program_blockContext>();
}

BNGParser::Program_blockContext* BNGParser::ProgContext::program_block(size_t i) {
  return getRuleContext<BNGParser::Program_blockContext>(i);
}

tree::TerminalNode* BNGParser::ProgContext::END() {
  return getToken(BNGParser::END, 0);
}


size_t BNGParser::ProgContext::getRuleIndex() const {
  return BNGParser::RuleProg;
}

void BNGParser::ProgContext::enterRule(tree::ParseTreeListener *listener) {
  auto parserListener = dynamic_cast<BNGParserListener *>(listener);
  if (parserListener != nullptr)
    parserListener->enterProg(this);
}

void BNGParser::ProgContext::exitRule(tree::ParseTreeListener *listener) {
  auto parserListener = dynamic_cast<BNGParserListener *>(listener);
  if (parserListener != nullptr)
    parserListener->exitProg(this);
}


std::any BNGParser::ProgContext::accept(tree::ParseTreeVisitor *visitor) {
  if (auto parserVisitor = dynamic_cast<BNGParserVisitor*>(visitor))
    return parserVisitor->visitProg(this);
  else
    return visitor->visitChildren(this);
}

